class ProfileModule(reactContext: ReactApplicationContext) :
  ReactContextBaseJavaModule(reactContext) {

  override fun getName() = "ProfileModule"

  @ReactMethod
  fun saveProfile(userId: String, nickname: String, promise: Promise) {
    val prefs = reactApplicationContext
      .getSharedPreferences("profile", Context.MODE_PRIVATE)
    prefs.edit()
      .putString("userId", userId)
      .putString("nickname", nickname)
      .apply()
    promise.resolve(true)
  }
}

@ReactMethod
fun upload(path: String, promise: Promise) {
  uploader.start(path, onDone = { response ->
    val result = Arguments.createMap().apply {
      putString("path", path)
      putInt("status", response.code)
    }
    reactApplicationContext
      .getJSModule(DeviceEventManagerModule.RCTDeviceEventEmitter::class.java)
      .emit("uploadDone", result)
    promise.resolve(result)
  }, onError = { e ->
    promise.reject("E_UPLOAD", e.message, e)
  })
}

@ReactMethod
fun scheduleReminder(id: Int, title: String, atMillis: Double, promise: Promise) {
  val context = reactApplicationContext
  val intent = Intent(context, ReminderReceiver::class.java).apply {
    putExtra("title", title)
  }
  val pending = PendingIntent.getBroadcast(
    context,
    id,
    intent,
    PendingIntent.FLAG_UPDATE_CURRENT
  )
  val alarm = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
  alarm.set(AlarmManager.RTC_WAKEUP, atMillis.toLong(), pending)
  promise.resolve(null)
}
